const __pageData = JSON.parse('{"title":"Federal Bureau of Investigation (FBI)","description":"","frontmatter":{"title":"Federal Bureau of Investigation (FBI)","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["agency","intelligence","music-industry"],"sources":["raw/a-journey-of-ever-changing-truths.md","raw/badlands-brief-07c.md","raw/badlands-brief-05f.md","raw/badlands-brief-094.md","raw/badlands-brief-2c5.md","raw/badlands-brief-40d.md","raw/badlands-brief-50d.md","raw/badlands-brief-559.md","raw/badlands-brief-509.md","raw/badlands-brief-625.md","raw/badlands-brief-6b4.md","raw/badlands-brief-739.md","raw/badlands-brief-884.md","raw/badlands-brief-8c2.md","raw/badlands-brief-990.md","raw/badlands-brief-c07.md","raw/badlands-brief-d3b.md","raw/badlands-brief-f87.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-06e.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-168.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-215.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-25f.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-2cb.md","raw/badlands-news-brief-34a.md","raw/badlands-news-brief-38a.md","raw/badlands-news-brief-384.md","raw/badlands-news-brief-3f0.md","raw/badlands-news-brief-3ae.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-46e.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-576.md","raw/badlands-news-brief-627.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-688.md","raw/badlands-news-brief-6e5.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-779.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-8cd.md"],"confidence":"low"},"headers":[],"relativePath":"entities/fbi.md","filePath":"entities/fbi.md","lastUpdated":null}');
